// A persistent open-world narrative layer. No autonomous LLM or confidential data.
const STORAGE='tp-islands-world-v2';let explorer={day:1,visits:0,island:0,cases:{},log:[],reforms:{},mode:'macro',weather:0};
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved&&saved.cases&&Array.isArray(saved.log))explorer={...explorer,...saved}}catch{}
let activeCase=null,activeRoom=0,worldInterval=null;
islands.push({name:'翡翠金融島',en:'EMERALD QUAY · IE',country:'愛爾蘭',flag:'🇮🇪',role:'融資與授權情境 / Fictional entities',person:'Aoife · 檔案保管員',face:'👩🏻‍💼',line:'「舊燈塔收藏的是歷史，銀行發生的是現在。別把兩張海圖混在一起。」',f:'故事中分別辨識授權、融資及資金管理',a:'依個別副本確認人員、資金與權利',r:'信用、流動性及技術風險分開確認',x:151,y:157,scale:.68,type:'market'},
{name:'協定公共島',en:'THE COMMONS · PUBLIC HARBOUR',country:'國際協商',flag:'🏛️',role:'公共場景 / 非集團公司',person:'小芽 · 調查聯絡員',face:'🧑🏻‍🌾',line:'「這裡不生產晶片。我們把證據、不同國家的說法與救濟途徑放在一起。」',f:'查核、協商與閱讀檔案的教學場景',a:'不適用公司資產分析',r:'不是營利事業，無集團報酬分配',x:862,y:123,scale:.58,type:'hq'});
// More room between buildings; all destinations remain keyboard accessible.
islands[0].x=443;islands[0].y=205;islands[0].scale=.96;islands[1].x=215;islands[1].y=337;islands[1].scale=.91;islands[2].x=651;islands[2].y=172;islands[2].scale=.78;islands[3].x=588;islands[3].y=367;islands[3].scale=.9;islands[4].x=815;islands[4].y=310;islands[4].scale=.74;
const locIcon={'倉庫':'📦','實驗室':'🧪','無塵室':'⚙️','產能塔':'🏭','市集':'📣','專利館':'💡','交易所':'⚖️','觀測台':'🔭','檔案室':'🗂️','服務站':'🛠️','種子溫室':'🌱','舊廠門':'🚚','銀行':'🏦','協商碼頭':'🤝','舊燈塔':'🥪','汽水博物館':'🥤','時間膠囊':'⏳','通關亭':'🛂','招工廣場':'🌾','保證櫃台':'🪙','潮汐水庫':'💧'};
const roomNames=['契約抽屜','決策現場','財務紀錄','另一方的說法'];const roomIcons=['📄','🧑‍🔬','📊','🗣️'];
function safe(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function saveWorld(){try{localStorage.setItem(STORAGE,JSON.stringify(explorer))}catch{}}
function entry(id){return explorer.cases[id]}
function knownCases(){return mysteries.filter(c=>entry(c.id))}
function finishedCases(){return mysteries.filter(c=>entry(c.id)?.endings.length>0)}
function record(t){explorer.log.unshift({day:explorer.day,text:t});explorer.log=explorer.log.slice(0,30);saveWorld()}
function discover(id){if(!entry(id)){explorer.cases[id]={universe:(explorer.day+explorer.visits+mysteries.findIndex(c=>c.id===id))%3,clues:[],resolved:false,endings:[],theory:null,note:'',day:explorer.day};record('新傳聞：'+mysteries.find(c=>c.id===id).title)}return entry(id)}
function localCases(i=explorer.island){return mysteries.filter(c=>c.island===i)}
function updatePassport(){const completed=finishedCases().length;$('#stamp-count').textContent=completed+' / '+mysteries.length;$('#passport').setAttribute('aria-label',`偵探護照，已調查 ${completed} 個事件`)}
function goIsland(i,travel=true){if(i<0||i>=islands.length)i=0;explorer.island=i;currentIsland=i;if(travel){explorer.visits++;if(explorer.visits%3===0)explorer.day++;record('抵達'+islands[i].name)}const pending=localCases(i).filter(c=>!entry(c.id)?.resolved);const rumor=pending[(explorer.day+explorer.visits)%Math.max(1,pending.length)]||localCases(i)[0];if(rumor)discover(rumor.id);$('#mobile-island').innerHTML=islands.map((o,j)=>`<option value="${j}" ${i===j?'selected':''}>${o.flag} ${o.name}</option>`).join('');renderIslandPanel(rumor);renderDistrict();renderHUD();renderFeed();drawWorldMap();updatePassport();saveWorld()}
selectIsland=(i)=>goIsland(i,true);
function drawWorldMap(){drawMap();const svg=$('#map-art svg');if(!svg)return;svg.setAttribute('aria-label','七座島嶼的開放世界探索地圖');const o=islands[explorer.island];svg.insertAdjacentHTML('beforeend',`<g id="world-map-overlay"><g pointer-events="none"><text x="88" y="425" font-size="20">🎃</text><text x="938" y="230" font-size="16">👻</text><circle class="traveller-halo" cx="${o.x+35}" cy="${o.y+22}" r="15" fill="none" stroke="#fff8db" stroke-width="2"/><text x="${o.x+35}" y="${o.y+25}" text-anchor="middle" font-size="14">🕵️</text>${islands.map((n,i)=>{const count=localCases(i).filter(c=>!entry(c.id)?.resolved).length;return `<g transform="translate(${n.x-25} ${i===5?n.y+112:n.y-87})"><rect width="73" height="20" rx="10" fill="#fff7da"/><text x="36" y="14" text-anchor="middle" font-size="9" fill="#788258">${count?'✦ '+count+' 處傳聞':'✿ 暫時平靜'}</text></g>`}).join('')}<g transform="translate(351 411)"><path d="M-17 0h34l-7 8h-20z" fill="#b99662"/><path d="M0 0v-24L-13-3H0" fill="#fff9df"/><animateTransform attributeName="transform" type="translate" values="351 411;405 400;351 411" dur="14s" repeatCount="indefinite"/></g></g></g>`);const weather=['☀ 日光','☁ 薄霧','☾ 夜訪'][explorer.day%3];$('.weather').textContent=`🎃 第 ${explorer.day} 日 · ${weather}`;$('#map-art').classList.toggle('night-map',explorer.day%3===2)}
function renderIslandPanel(rumor){const o=islands[explorer.island];$('#island-panel').innerHTML=`<div class="island-kicker">EXPLORING · ${safe(o.country)}</div><div class="country"><span class="flag">${o.flag}</span><div><h2>${o.name}</h2><small>${o.en}</small></div></div><span class="role-tag">${o.role}</span><div class="resident"><span class="portrait">${o.face}</span><span><b>${o.person.split(' · ')[0]}</b><small>${o.person.split(' · ')[1]}</small></span></div><p class="speech">${o.line}</p>${rumor?`<div class="rumor-note"><small>✦ 剛剛聽到的消息</small><b>${rumor.title}</b><p>${rumor.rumor}</p><button class="primary" id="follow-rumor">順著線索走 →</button></div>`:'<div class="rumor-note">碼頭暫時平靜，前往其他島嶼看看。</div>'}<button class="text-button panel-street" id="walk-street">⌕ 走進島上街區</button>`;if(rumor)$('#follow-rumor').onclick=()=>openCase(rumor.id);$('#walk-street').onclick=()=>$('#district').scrollIntoView({behavior:'smooth'})}
function renderHUD(){const c=knownCases().length,f=finishedCases().length;$('#world-hud').innerHTML=`<div class="world-time"><span class="time-sun">${explorer.day%3===2?'☾':'☀'}</span><span><b>第 ${explorer.day} 日 · 晶芽群島</b><small>時間推進會改變偶遇的傳聞；已接案件不會消失。</small></span></div><div class="world-stats"><span><b>${c}</b> 已知事件</span><span><b>${f}</b> 已解謎題</span><span><b>${Object.values(explorer.cases).reduce((n,v)=>n+v.endings.length,0)}</b> 已見時間線</span></div><button class="choice" id="world-wait">◷ 散步到下一日</button>`;$('#world-wait').onclick=()=>{explorer.day++;record('時鐘前進了一日，新的居民帶來消息。');goIsland(explorer.island,false);toast('新的一天，島上又有不同的傳聞。')}}
function renderDistrict(){const list=localCases();const o=islands[explorer.island];$('#district').innerHTML=`<div class="section-heading"><div><div class="eyebrow">WALK INTO THE NEIGHBOURHOOD</div><h2>${o.name} · 今天去哪裡走走？</h2></div><span class="street-hint">自由探索 · 不必依序完成</span></div><div class="district-shell"><div class="street-scene"><div class="street-sky"><span>☁</span><span>✦</span><span>☁</span></div><div class="street-path"></div>${list.map((c,i)=>`<button class="street-building house-${i%5} ${entry(c.id)?.resolved?'visited-house':''}" data-place="${c.id}" style="--position:${(i+1)/(list.length+1)*100}%" aria-label="探索${c.place}：${entry(c.id)?c.title:'有人留下了線索'}"><span class="roof"></span><span class="house-face"><span>${c.icon}</span><i></i><i></i></span><span class="street-pin">${entry(c.id)?.resolved?'✿':entry(c.id)?'!':'?'}</span><b>${c.place}</b><small>${entry(c.id)?.resolved?'曾有故事的地方':entry(c.id)?'已有線索':'走近看看'}</small></button>`).join('')}<span class="street-tree one">🌳</span><span class="street-tree two">🌳</span><span class="street-pumpkin">🎃</span><span class="street-walker">🕵🏻</span><span class="street-sign">${o.flag} ${o.country}</span></div>${Object.values(explorer.reforms||{}).filter(r=>r.island===explorer.island).length?`<div class="district-reforms"><b>🌱 企業在這一期做了改變</b>${Object.values(explorer.reforms||{}).filter(r=>r.island===explorer.island).slice(-2).map(r=>`<p>${r.lesson}<small>保留前期例示調增所得 ${r.amount} 的紀錄；改善不撤銷過往調整。</small></p>`).join('')}</div>`:''}<div class="street-bottom"><span>點建築拜訪居民，事件將加入手帳。所有事件皆可重訪。</span><button class="text-button" id="island-dossier">查看這座島的公司與交易 ↗</button></div></div>`;document.querySelectorAll('[data-place]').forEach(e=>e.onclick=()=>{discover(e.dataset.place);openCase(e.dataset.place);renderHUD();renderFeed();drawWorldMap()});$('#island-dossier').onclick=showCompany}
function renderFeed(){$('#world-feed').innerHTML=`<div class="section-heading"><div><div class="eyebrow">LIFE GOES ON</div><h2>消息在海風裡流動。</h2></div><button class="text-button" id="open-journal">打開偵探手帳 ↗</button></div><div class="feed-grid">${explorer.log.slice(0,3).map(x=>`<div class="feed-note"><small>第 ${x.day} 日 · 港口便箋</small><p>${safe(x.text)}</p></div>`).join('')}</div>`;$('#open-journal').onclick=showJournal}
function renderCase(){const c=mysteries.find(x=>x.id===activeCase),s=entry(c.id),w=c.worlds[s.universe];const unlocked=i=>i===0||(i===1||i===2?s.clues.includes(0):s.clues.includes(1));openModal('偶遇事件 · '+c.place,`<div class="case-header"><div><div class="eyebrow">${c.era||'AN ENCOUNTER IN THE ARCHIPELAGO'}</div><h2>${c.icon} ${c.title}</h2></div><span class="case-status">${s.resolved?'✿ 已留足跡':'⌕ 調查中'}</span></div><p class="lead">${c.rumor}</p>${s.priorFinding?`<div class="note"><b>下一期改善支線</b><br>前期結論：${s.priorFinding}；例示所得調增 ${s.priorAmount}。企業改變了本期安排，請重新查證。前期調整不會因後來改善而自動撤銷。</div>`:''}<div class="case-tag-row">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="investigation-layout"><div><div class="evidence-room"><div class="room-title">${islands[c.island].name} · ${c.place}<small>點物件找線索，先閱讀合約，再追查決策與帳務。</small></div><div class="room-floor"></div>${roomNames.map((n,i)=>`<button class="room-object object-${i} ${s.clues.includes(i)?'found':''}" data-object="${i}" ${!unlocked(i)?'disabled':''}><span>${roomIcons[i]}</span><b>${n}</b><small>${s.clues.includes(i)?'已收入案卷':unlocked(i)?'查看線索':i===3?'先訪問決策現場':'先開啟契約'}</small></button>`).join('')}<span class="room-plant">🪴</span></div><div id="clue-reveal" class="clue-reveal">${s.clues.includes(activeRoom)?clueText(c,s,activeRoom):'<span>🕯️</span><p>桌面、人物和帳冊都可能留下證據。<br>先從契約抽屜開始。</p>'}</div><div class="detective-note"><label>你的推理筆記 <small>僅存在此瀏覽器，不會送出</small><textarea id="case-note" rows="2" placeholder="誰實際決定？誰有能力承擔？還缺哪一份資料？">${safe(s.note)}</textarea></label></div></div><aside class="case-board"><div class="eyebrow">YOUR EVIDENCE BOARD</div><h3>把蛛絲馬跡串起來。</h3><p>${c.question||'合約與實際行為是否一致？現有報酬是否反映真正的經濟貢獻？'}</p><div class="evidence-pins">${roomNames.map((n,i)=>`<button data-revisit="${i}" ${!s.clues.includes(i)?'disabled':''}>${s.clues.includes(i)?'●':'○'} ${n}</button>`).join('')}</div><span class="board-count">已查 ${s.clues.length} / 4 份資料 · 不以分數認證定位</span><div class="board-divider"></div><label class="hypothesis-label">你的初步假說<select id="theory-select"><option value="">請依證據選擇</option>${c.worlds.map((q,i)=>`<option value="${i}" ${s.theory===i?'selected':''}>${String.fromCharCode(65+i)} · ${q.finding}</option>`).join('')}<option value="more" ${s.theory==='more'?'selected':''}>證據仍不足，繼續補查</option></select></label><button class="primary" id="submit-theory">整理案情，提出結論 →</button><p class="board-caution">每一條時間線都有不同的事實。提出的假說不會改變已查得的證據。</p>${s.resolved?'<button class="choice" id="reopen-ending">重看結局與平行世界 ↗</button>':''}</aside></div><details class="case-codex"><summary>📖 小芽的調查手冊 · 概念、依據與史實</summary>${codex(c)}</details><div class="case-exit"><button class="text-button" id="return-street">← 回到街區，保留目前進度</button><span>調增所得、稅額與罰鍰分開；故事金額均為假設。</span></div>`);
document.querySelectorAll('[data-object],[data-revisit]').forEach(e=>e.onclick=()=>{const i=Number(e.dataset.object??e.dataset.revisit);if(!s.clues.includes(i))s.clues.push(i);activeRoom=i;saveWorld();renderCase()});$('#case-note').oninput=e=>{s.note=e.target.value;saveWorld()};$('#theory-select').onchange=e=>{s.theory=e.target.value==='more'?'more':e.target.value===''?null:Number(e.target.value);saveWorld()};$('#submit-theory').onclick=()=>submitTheory(c,s);$('#return-street').onclick=()=>{$('#modal').close();goIsland(c.island,false);$('#district').scrollIntoView({behavior:'smooth'})};if($('#reopen-ending'))$('#reopen-ending').onclick=()=>showEnding(c,s)}
function clueText(c,s,i){const w=c.worlds[s.universe];return `<div class="clue-meta"><span>${roomIcons[i]} 線索 ${String(i+1).padStart(2,'0')} · ${roomNames[i]}</span><span>教學情境文件</span></div><p>${w.clues[i]}</p><div class="clue-question">${['先記錄誰被安排做什麼；契約本身還不是完整結論。','對照人員能力、實際決策與控制，別只看簽名或職稱。','確認金額的性質、期間、分部及是否已被其他報酬反映。','回應反證，保留合理疑點；不要只挑支持原先想法的資料。'][i]}</div>`}
function openCase(id){activeCase=id;activeRoom=entry(id)?.clues.at(-1)??0;discover(id);renderCase();updatePassport()}
function submitTheory(c,s){const verdict=TPLogic.resolve(s);if(verdict==='choose'){toast('先選一個初步假說，或選擇繼續補查。');return}if(verdict==='incomplete'){openModal('未完的案卷 · 補查支線',`<div class="eyebrow">AN OPEN ENDING · 尚未形成實體結論</div><h2>🕯️ 證據還需要往前走一步。</h2><p class="lead">${s.theory==='more'?'你保留了疑問。補查是可成立的程序選擇，不是稅額為零的結論。':'目前還沒看完正反證據，不能把初步想法當成已證實的核定結果。'}</p><div class="note">待查：${roomNames.filter((_,i)=>!s.clues.includes(i)).join('、')||c.question||'實際決策、財務能力、比較可靠性及未被反映的報酬'}。<br><b>所得調整：未定；稅額：未定。</b></div><button class="primary" id="continue-investigation">返回現場，繼續查證 →</button>`);$('#continue-investigation').onclick=renderCase;return}if(verdict==='contradiction'){const a=c.worlds[s.theory],w=c.worlds[s.universe];openModal('推論遇見反證',`<div class="eyebrow">A THEORY IS NOT A FINDING</div><h2>🔎 這個結局，證據還接不上。</h2><p class="lead">你提出：${a.finding}</p><div class="feedback"><b>請回頭對照這兩份證據</b><br>${w.clues[1]}<br>${w.clues[3]}</div><p class="lead">若現在直接採用，你可能錯置功能風險或金額。本案尚未作成調整。平行宇宙可以更換事實，但不能靠換答案抹掉這條時間線的紀錄。</p><button class="primary" id="rethink">把反證釘回推理板 →</button>`);$('#rethink').onclick=renderCase;return}s.resolved=true;if(!s.endings.includes(s.universe))s.endings.push(s.universe);record('完成調查：'+c.title+' · '+c.worlds[s.universe].label);showEnding(c,s);updatePassport();renderHUD();drawWorldMap()}
function tax(c,w,rate=20){return TPLogic.tax(w.amount,rate)}
function showEnding(c,s){const w=c.worlds[s.universe];openModal('結局 · '+w.label,`<div class="eyebrow">THE TRUTH OF THIS TIMELINE</div><h2>${c.icon} ${w.label}</h2><p class="lead">${w.finding}</p><div class="ending-evidence"><b>結論怎麼從證據長出來？</b><ol><li>${w.clues[0]}</li><li>${w.clues[1]}</li><li>${w.clues[2]}</li><li>已回應反證：${w.clues[3]}</li></ol></div><div class="outcome-metrics"><div><small>${c.taxKind==='group'?'淨等值所得差額（雙邊示例）':'本案例示調增所得'}</small><b>${w.amount}</b></div><div><small>${c.taxKind==='group'?'集團淨新增稅（示例）':'單一主體新增稅（示例）'}</small><b id="ending-tax">${tax(c,w)}</b></div><label>統一假設稅率 %<input type="number" id="universe-rate" value="20" min="0" max="100" step="0.1"></label></div><p class="tax-explanation">對象：${c.stakeholder}。${w.formula}。<br>${c.taxKind==='group'?'此案另展示雙邊對應稅額；假設雙方相同稅率。':'新增稅簡化為調增所得 × 假設稅率；不是該國法定稅率。'}未含虧損扣抵、抵減、利息、扣繳、其他稅目及罰鍰；未經程序核定。</p><div class="note">✿ ${w.lesson}</div><h3 class="parallel-title">如果你走進另一個平行宇宙……</h3><p class="lead small-lead">下面改變的是契約、行為或可比較事實，不是任選較低稅額。同一事實不能藉選項任意改稅。</p><div class="parallel-grid">${c.worlds.map((q,i)=>`<article class="parallel-card ${i===s.universe?'this-universe':''}"><small>${i===s.universe?'● 你現在的世界':'○ 平行時間線 '+String.fromCharCode(65+i)}</small><h4>${q.label}</h4><p><b>關鍵分歧</b><br>${q.clues[1]}</p><div><span>例示所得 +${q.amount}</span><b>例示新增稅 <em data-parallel-tax="${i}">${tax(c,q)}</em></b></div><p class="parallel-finding">${q.finding}</p>${i===s.universe?'<span class="current-label">目前所在</span>':`<button class="choice" data-timeline="${i}">進入這個世界，重新蒐證 →</button>`}</article>`).join('')}</div><details class="case-codex"><summary>這些結局，對應哪些觀念與真實資料？</summary>${codex(c)}</details><div class="note"><b>下一期的營運會怎麼改變？</b><br>${c.next}</div><div class="choice-row"><button class="primary" id="ending-return">回到群島，帶著線索出發 →</button><button class="choice" id="next-season">走向改善後的下一期 →</button><button class="choice" id="ending-journal">查看偵探手帳</button></div>`);$('#universe-rate').oninput=e=>{let v=Number(e.target.value);if(e.target.value===''||!Number.isFinite(v)||v<0||v>100){$('#ending-tax').textContent='請輸入 0–100';return}$('#ending-tax').textContent=tax(c,w,v).toLocaleString();document.querySelectorAll('[data-parallel-tax]').forEach(el=>el.textContent=tax(c,c.worlds[+el.dataset.parallelTax],v).toLocaleString())};document.querySelectorAll('[data-timeline]').forEach(e=>e.onclick=()=>{Object.assign(s,TPLogic.changeTimeline(s,+e.dataset.timeline));activeRoom=0;record('進入平行時間線：'+c.title+' · '+c.worlds[s.universe].label);renderCase()});$('#ending-return').onclick=()=>{$('#modal').close();explorer.day++;record('下一期提醒：'+c.next);goIsland(c.island,false)};$('#ending-journal').onclick=showJournal;$('#next-season').onclick=()=>{s.priorFinding=w.finding;s.priorAmount=w.amount;explorer.reforms=explorer.reforms||{};explorer.reforms[c.id]={island:c.island,lesson:c.next,amount:w.amount};const better=c.worlds.reduce((idx,q,i)=>q.amount<c.worlds[idx].amount?i:idx,0);Object.assign(s,TPLogic.changeTimeline(s,better));explorer.day++;record('企業進入改善支線：'+c.title+'；前期調整仍保留。');activeRoom=0;saveWorld();renderCase();renderHUD();renderDistrict();drawWorldMap()}}
function codex(c){const sources=['oecd',...(c.sources||[])];return `<div class="codex-inner"><b>本事件的分析座標</b><p>${c.ref}</p><p>隱藏的閱讀索引：OECD TPG ${c.chapters.map(x=>'Chapter '+x).join('、')}。閱讀次序由你決定；這些索引只放在案卷裡。</p>${c.history?`<div class="historical-note"><b>史實／判決檔案 · 與遊戲假設分開</b><p>${c.history}</p></div>`:''}<p>${c.worlds.map(w=>w.lesson).join(' ')}</p><ul>${[...new Set(sources)].map(k=>`<li><a href="${CASE_SOURCES[k].url}" target="_blank" rel="noopener">${CASE_SOURCES[k].label} ↗</a></li>`).join('')}</ul><p class="sim-fine">所有角色、線索、假設金額及平行結局為原創教學案例，不是稅局認定或法律建議；資料查閱日 2026-10-28。原版指引採 2022 版，Amount B 另列 2025 文件，不宣稱涵蓋其後所有修訂。真實案件須依適用年度、法律及協定檢查。</p></div>`}
function showJournal(){openModal('偵探手帳 · 你自己走出的路',`<div class="eyebrow">THE ISLANDS REMEMBER YOUR FOOTSTEPS</div><h2>把傳聞變成證據，把證據變成理解。</h2><p class="lead">群島上有 ${mysteries.length} 個事件、${mysteries.length*3} 條事實時間線，還有「補查中」的開放結局。此瀏覽器已發現 ${knownCases().length} 個事件，已探索 ${Object.values(explorer.cases).reduce((n,s)=>n+s.endings.length,0)} 條完整時間線。</p><div class="journal-list">${knownCases().length?knownCases().map(c=>{const s=entry(c.id);return `<button class="journal-entry" data-journal-case="${c.id}"><span>${c.icon}</span><div><b>${c.title}</b><small>${islands[c.island].name} · ${c.place} · 證據 ${s.clues.length}/4 · 已見結局 ${s.endings.length}/3</small></div><em>${s.resolved?'✿ 已查明':'⌕ 待追查'}</em></button>`}).join(''):'<div class="note">先前往一座島嶼，和居民聊聊。</div>'}</div><div class="note">未發現的事件不以章節清單列出。前往其他島嶼的建築，或散步到下一日尋找消息。進度、案卷與筆記僅存於此瀏覽器。</div><button class="primary" id="journal-back">回到群島探索 →</button>`);document.querySelectorAll('[data-journal-case]').forEach(e=>e.onclick=()=>openCase(e.dataset.journalCase));$('#journal-back').onclick=()=>$('#modal').close()}
showChapters=showJournal;showPassport=showJournal;
showChapter=function(i){const target=mysteries.find(c=>c.chapters.includes(chapters[i]?.[0]));if(target){$('#modal').close();goIsland(target.island);openCase(target.id)}};
function showCompany(){const o=islands[explorer.island];openModal('公司與交易 · '+o.name,`<div class="eyebrow">MICRO ↔ MACRO</div><h2>${o.flag} ${o.name}</h2><div class="choice-row"><button class="choice" id="dossier-micro">微觀 · FAR 與決策</button><button class="choice" id="dossier-macro">宏觀 · 關係與交易結構</button></div><div id="company-view"></div>`);const micro=()=>{$('#company-view').innerHTML=`<table><tr><th>角色</th><td>${o.role}</td></tr><tr><th>F 功能</th><td>${o.f}</td></tr><tr><th>A 資產</th><td>${o.a}</td></tr><tr><th>R 風險</th><td>${o.r}</td></tr></table><div class="note">這是島嶼基本設定；個別副本的時間線可能改變實際功能與風險，必須以該案線索重做分析。</div>`};$('#dossier-micro').onclick=micro;$('#dossier-macro').onclick=()=>{$('#company-view').innerHTML=`<p class="lead">基礎世界觀：新加坡森光總部持有臺灣、日本、荷蘭、美國及愛爾蘭故事子公司各 100%。國稅查核島屬查核及協商場景，會計師諮詢島為獨立顧問場景，均非集團子公司。歷史與判決副本有自己的架構。</p><table><tr><th>交易</th><th>要追查的事實</th></tr><tr><td>JP → SG 研發服務</td><td>誰控制研發、DEMPE 與技術權利？</td></tr><tr><td>TW → SG 製造服務／製程使用</td><td>產能、良率、規模利益與技術如何補償？</td></tr><tr><td>SG → NL／US 晶片銷售</td><td>誰決定備貨、承擔庫存與市場推廣？</td></tr><tr><td>IE ↔ 集團融資／授權</td><td>分別辨認金融風險、無形資產與權利金。</td></tr></table><div class="note">持股建立關係情境，不決定全部利潤歸屬。國籍也不是功能風險的替代指標。</div>`};micro()}
function showTools(){openModal('偵探的工具袋',`<h2>🔎 先問問題，再找工具。</h2><div class="tool-list"><button class="journal-entry" id="tool-risk"><span>🧭</span><div><b>六步驟風險指南</b><small>辨識 → 合約 → 行為 → 控制／資力 → 配置 → 報酬</small></div></button><button class="journal-entry" id="tool-tax"><span>🏛️</span><div><b>查核、所得調整、稅額與救濟</b><small>程序與分析分開，補稅與處罰分開</small></div></button><button class="journal-entry" id="tool-research"><span>🧪</span><div><b>受託研發的偵查現場</b><small>前往櫻川島，親自找決策紀錄</small></div></button></div>`);$('#tool-risk').onclick=()=>startRisk();$('#tool-tax').onclick=showAuditLaw;$('#tool-research').onclick=()=>{goIsland(2);openCase('research')}}
function showAuditLaw(){openModal('國稅局碼頭 · 概念流程',`<h2>🏛️ 從疑點到核定，證據不能跳步。</h2><ol class="audit-steps"><li>辨識交易與疑點，請求資料；風險訊號並非已證實避稅。</li><li>分析實際 FAR、方法、可比較性及報酬，聽取並回應企業反證。</li><li>臺灣一般情境依所得稅法第 43 條之 1 及查核準則辦理報核、核定；OECD 本身不是補稅法源。</li><li>依核定及適用規定處理稅額與繳納，處罰另依查核準則第 34 條及相關法律要件審認。</li><li>另依適用規定檢查國內救濟；跨境對應調整及 MAP 須檢查適用協定與條件，不自動發生。</li></ol><div class="note">遊戲結局只是具明確假設的分析結果與算術，沒有取代報核、核定、救濟或協商。外國副本不套用臺灣程序。</div><div class="citation"><a href="https://law-out.mof.gov.tw/LawContent.aspx?id=FL005935" target="_blank" rel="noopener">所得稅法 ↗</a>；<a href="${CASE_SOURCES.tw.url}" target="_blank" rel="noopener">TP 查核準則第 2、33–35 條 ↗</a>；<a href="${OECD}" target="_blank" rel="noopener">OECD TPG IV ↗</a></div>`)}
function showWorldGuide(){openModal('小芽的開放世界指南',`<div class="eyebrow">WELCOME, DETECTIVE</div><h2>🕵🏻 把自己交給一場偶遇。</h2><p class="lead">點一座島，走進有「？」的建築。居民會交給你一件不尋常的小事：一張帳單、一批滯銷庫存，或一本不能公開的研發筆記。</p><div class="guide-route"><span>🏝 拜訪島嶼</span><span>✦ 遇見事件</span><span>🔍 調查物件與人物</span><span>🧷 提出並檢驗假說</span><span>⏳ 走進平行結局</span></div><p class="lead">你可以自由走訪 ${mysteries.length} 件事；OECD 的概念及索引藏在每份案卷的調查手冊。每件事有三套不同事實、不同所得及稅額結果，也可以保留「尚待補查」。</p><div class="note">先試試「櫻川研究島 → 實驗室」。你會發現，「受託研發」可能是一份真實分工，也可能只是一個招牌。代理、居民及世界演進為規則式模擬，未串接生成式 AI。</div><button class="primary" id="guide-start">前往櫻川島，找葵聊聊 →</button>`);$('#guide-start').onclick=()=>{$('#modal').close();goIsland(2);$('#district').scrollIntoView({behavior:'smooth'})}}
function worldSources(){openModal('群島圖書館 · 閱讀說明',`<h2>每個故事，都有可以追查的依據。</h2><p class="lead">目前有 ${mysteries.length} 個原創副本，覆蓋 OECD TPG 2022 第 I–X 章的重要觀念，但不是所有 TP 問題的窮盡清單。章節只作案卷內的閱讀索引；探索路線由你自己決定。</p><p class="lead">每案三條時間線改變的是經濟事實。金額是清楚標示的教學假設，既不使用通用常規利潤率，也不把玩家選項當作法律裁量。未看完反證或推論矛盾時，不直接產生已核定補稅。</p><div class="historical-note"><b>原創案卷</b><p>所有企業、交易與案例均為虛構。案卷原文、受訪人說法與平行世界假設分開閱讀；不同年度與交易範圍不直接混用。</p></div><ul class="source-list">${Object.values(CASE_SOURCES).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${s.label} ↗</a></li>`).join('')}</ul><p class="lead small-lead">進度與筆記存在目前瀏覽器。網站保留原創療癒島嶼插畫及秋日氣氛；規則式情節，不宣稱即時 AI 自主生成。來源查閱日：2026-10-28。</p>`)}
document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>{const n=e.dataset.nav;if(n==='chapters')showJournal();else if(n==='lab')showTools();else{$('#modal').close();(n==='sim'?$('#district'):$('.explorer')).scrollIntoView({behavior:'smooth'})}});
$('#passport').onclick=showJournal;$('#guide').onclick=showWorldGuide;$('#sources').onclick=worldSources;$('#all-chapters').onclick=showJournal;$('#risk-card').onclick=()=>openCase('lrd');$('#mobile-island').onchange=e=>goIsland(+e.target.value);$('#island-mode').onclick=()=>{$('#island-mode').classList.add('selected');$('#flow-mode').classList.remove('selected');drawWorldMap()};$('#flow-mode').onclick=()=>{$('#flow-mode').classList.add('selected');$('#island-mode').classList.remove('selected');drawWorldMap()};$('#reset-map').onclick=()=>goIsland(0);goIsland(explorer.island,false);
